%[text] # BEV System Model - Simulation Case
modelName = "BEV_system_model";
load_system(modelName)
BEV_useBasic %[output:9e0f1450]
VehSpdRef_loadCase_SimpleDrivePattern( ... %[output:group:1b433959] %[output:67783457]
  ModelName = modelName, ... %[output:67783457]
  TargetSubsystemPath = "/Controller & Environment/Vehicle speed reference") %[output:group:1b433959] %[output:67783457]
simOut = sim(modelName);
simData = extractTimetable(simOut.logsout);
fig = BEV_ResultsCompactPlot(SimData = simData, PlotTemperature = false); %[output:33d3450d]
